BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "availability_animateurleave" ("id" char(32) NOT NULL PRIMARY KEY, "start_date" date NOT NULL, "end_date" date NOT NULL, "reason" text NOT NULL, "status" varchar(20) NOT NULL, "animateur_id" char(32) NOT NULL REFERENCES "users_animateurprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "availability_availability" ("id" char(32) NOT NULL PRIMARY KEY, "date" date NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "is_blocked" bool NOT NULL, "animateur_id" char(32) NOT NULL REFERENCES "users_animateurprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "availability_weeklyschedule" ("id" char(32) NOT NULL PRIMARY KEY, "day_of_week" integer NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "is_active" bool NOT NULL, "animateur_id" char(32) NOT NULL REFERENCES "users_animateurprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "bookings_booking" ("id" char(32) NOT NULL PRIMARY KEY, "event_date" date NOT NULL, "start_time" time NOT NULL, "children_count" integer unsigned NOT NULL CHECK ("children_count" >= 0), "estimated_price" decimal NOT NULL, "final_price" decimal NOT NULL, "status" varchar(20) NOT NULL, "address" varchar(255) NOT NULL, "city" varchar(100) NOT NULL, "location_zip" varchar(20) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "service_id" char(32) NOT NULL REFERENCES "services_service" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "child_age" integer unsigned NULL CHECK ("child_age" >= 0), "child_name" varchar(100) NOT NULL, "contact_phone" varchar(20) NOT NULL, "admin_notification_sent_at" datetime NULL, "cancellation_email_sent_at" datetime NULL, "confirmation_email_sent_at" datetime NULL, "cancelled_by" varchar(10) NOT NULL, "cancellation_reason" text NOT NULL);
CREATE TABLE "bookings_bookingassignment" ("id" char(32) NOT NULL PRIMARY KEY, "status" varchar(20) NOT NULL, "assigned_at" datetime NOT NULL, "animateur_id" char(32) NOT NULL REFERENCES "users_animateurprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "booking_id" char(32) NOT NULL REFERENCES "bookings_booking" ("id") DEFERRABLE INITIALLY DEFERRED, "notification_sent_at" datetime NULL, "responded_at" datetime NULL);
CREATE TABLE "bookings_bookingoption" ("id" char(32) NOT NULL PRIMARY KEY, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "unit_price" decimal NOT NULL, "booking_id" char(32) NOT NULL REFERENCES "bookings_booking" ("id") DEFERRABLE INITIALLY DEFERRED, "option_id" char(32) NOT NULL REFERENCES "services_option" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "contact_contactmessage" ("name" varchar(200) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "message" text NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "id" char(32) NOT NULL PRIMARY KEY);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action_time" datetime NOT NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "media_mediagallery" ("id" char(32) NOT NULL PRIMARY KEY, "media_url" varchar(200) NOT NULL, "type" varchar(10) NOT NULL, "title" varchar(200) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "service_id" char(32) NULL REFERENCES "services_service" ("id") DEFERRABLE INITIALLY DEFERRED, "file" varchar(100) NULL);
CREATE TABLE "payments_payment" ("stripe_session_id" varchar(255) NOT NULL UNIQUE, "stripe_payment_intent" varchar(255) NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "booking_id" char(32) NOT NULL REFERENCES "bookings_booking" ("id") DEFERRABLE INITIALLY DEFERRED, "failure_email_sent_at" datetime NULL, "id" char(32) NOT NULL PRIMARY KEY);
CREATE TABLE "reviews_review" ("rating" smallint unsigned NOT NULL CHECK ("rating" >= 0), "comment" text NOT NULL, "created_at" datetime NOT NULL, "booking_id" char(32) NOT NULL UNIQUE REFERENCES "bookings_booking" ("id") DEFERRABLE INITIALLY DEFERRED, "id" char(32) NOT NULL PRIMARY KEY);
CREATE TABLE "services_option" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "description" text NOT NULL, "price" decimal NOT NULL, "pricing_type" varchar(20) NOT NULL, "is_active" bool NOT NULL, "service_id" char(32) NOT NULL REFERENCES "services_service" ("id") DEFERRABLE INITIALLY DEFERRED, "image_url" varchar(500) NULL);
CREATE TABLE "services_service" ("title" varchar(200) NOT NULL, "description" text NOT NULL, "base_price" decimal NOT NULL, "duration_minutes" integer unsigned NOT NULL CHECK ("duration_minutes" >= 0), "category" varchar(20) NOT NULL, "is_active" bool NOT NULL, "max_children" integer unsigned NOT NULL CHECK ("max_children" >= 0), "min_children" integer unsigned NOT NULL CHECK ("min_children" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "badge_label" varchar(50) NOT NULL, "image_url" varchar(500) NULL, "id" char(32) NOT NULL PRIMARY KEY);
CREATE TABLE "users_animateurprofile" ("id" char(32) NOT NULL PRIMARY KEY, "bio" text NOT NULL, "phone" varchar(20) NOT NULL, "avatar_url" varchar(200) NOT NULL, "rating" real NOT NULL, "user_id" char(32) NOT NULL UNIQUE REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_user" ("password_hash" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "role" varchar(10) NOT NULL, "is_verified" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "id" char(32) NOT NULL PRIMARY KEY);
CREATE TABLE "users_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
