CREATE INDEX "bookings_bookingassignment_booking_id_a97cbe75" ON "bookings_bookingassignment" ("booking_id");
CREATE UNIQUE INDEX "availability_weeklyschedule_animateur_id_day_of_week_start_time_end_time_451ab837_uniq" ON "availability_weeklyschedule" ("animateur_id", "day_of_week", "start_time", "end_time");
CREATE INDEX "availability_weeklyschedule_animateur_id_91f7b542" ON "availability_weeklyschedule" ("animateur_id");
